use std::collections::BTreeMap; use serde::{Deserialize,Serialize}; use super::{error::{AdmissionError,AdmissionErrorKind,Result},subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct IdempotencyRecord{pub key:String,pub subject:SubjectId,pub request_digest:String,pub result_digest:String,pub epoch:u64}
#[derive(Clone,Debug,Default,Serialize,Deserialize)] pub struct IdempotencyStore{records:BTreeMap<String,IdempotencyRecord>}
impl IdempotencyStore{pub fn check(&self,key:&str,request:&str)->Result<Option<&IdempotencyRecord>>{match self.records.get(key){None=>Ok(None),Some(r)if r.request_digest==request=>Ok(Some(r)),Some(r)=>Err(AdmissionError::new(AdmissionErrorKind::Conflict,"idempotency.conflict",format!("key {key} already bound to {}",r.request_digest)).subject(r.subject.key()))}}pub fn record(&mut self,r:IdempotencyRecord)->Result<()>{if let Some(old)=self.records.get(&r.key){if old.request_digest!=r.request_digest||old.result_digest!=r.result_digest{return Err(AdmissionError::new(AdmissionErrorKind::Conflict,"idempotency.rebind","idempotency key cannot be rebound").subject(r.subject.key()))}return Ok(())}self.records.insert(r.key.clone(),r);Ok(())}}